import React from 'react';
import { 
  Container, 
  Typography, 
  Paper, 
  Grid, 
  Box, 
  List, 
  ListItem, 
  ListItemIcon, 
  ListItemText,
  useTheme,
  Button
} from '@mui/material';
import { 
  Computer, 
  Speed, 
  Security, 
  CloudQueue,
  Download
} from '@mui/icons-material';

const Home = () => {
  const theme = useTheme();

  return (
    <Box sx={{ 
      minHeight: '100vh',
      backgroundImage: 'linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url("/fondo.jpg")',
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
      backgroundAttachment: 'fixed',
      position: 'relative',
      py: 0,
      color: theme.palette.text.primary
    }}>
      {/* Contenedor relativo para todo el contenido */}
      <Box sx={{ position: 'relative' }}>
        {/* Imagen de encabezado a todo ancho */}
        <Box
          sx={{
            width: '100%',
            overflow: 'hidden',
            borderBottom: `1px solid ${theme.palette.divider}`
          }}
        >
          <Box
            component="img"
            src="cluster-background.png" 
            alt="Imagen del Clúster Raspberry Pi"
            sx={{
              width: '100%',
              height: 400,
              objectFit: 'cover',
              objectPosition: 'center',
              display: 'block'
            }}
          />
        </Box>

        {/* Container principal para el contenido */}
        <Container maxWidth="lg" sx={{ py: 8 }}>
          {/* Hero Section */}
          <Box sx={{ 
            textAlign: 'center', 
            mb: 10,
            color: theme.palette.common.white
          }}>
            <Typography 
              variant="h3" 
              component="h1"
              sx={{ 
                fontWeight: 300,
                mb: 3,
                letterSpacing: 1
              }}
            >
              Soluciones de Clúster con Raspberry Pi
            </Typography>
            <Typography 
              variant="h6" 
              component="h2"
              sx={{ 
                fontWeight: 300,
                maxWidth: 800,
                margin: '0 auto',
                lineHeight: 1.6
              }}
            >
              Infraestructura escalable y eficiente para sus necesidades de computación distribuida
            </Typography>
          </Box>

          {/* Content Grid */}
          <Grid container spacing={6} sx={{ mb: 8 }}>
            {/* Main Content */}
            <Grid item xs={12} md={8}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 6, 
                  mb: 4,
                  background: theme.palette.background.paper,
                  borderRadius: 1,
                  border: `1px solid ${theme.palette.divider}`,
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    boxShadow: theme.shadows[6]
                  }
                }}
              >
                <Typography 
                  variant="h4" 
                  component="h3"
                  sx={{ 
                    fontWeight: 400,
                    mb: 4,
                    color: theme.palette.text.primary,
                    position: 'relative',
                    '&:after': {
                      content: '""',
                      display: 'block',
                      width: 60,
                      height: 2,
                      backgroundColor: theme.palette.primary.main,
                      mt: 2
                    }
                  }}
                >
                  ¿Qué es un Clúster de Raspberry Pi?
                </Typography>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    lineHeight: 1.8,
                    color: theme.palette.text.secondary,
                    mb: 4,
                    fontSize: '1.1rem'
                  }}
                >
                  Un Clúster de Raspberry Pi es un conjunto de computadoras Raspberry Pi 
                  conectadas entre sí que trabajan de manera coordinada para ejecutar 
                  aplicaciones distribuidas. Cada Raspberry Pi actúa como un nodo en el 
                  Clúster, proporcionando recursos de CPU, memoria y almacenamiento.
                </Typography>

                <Typography 
                  variant="h4" 
                  component="h3"
                  sx={{ 
                    fontWeight: 400,
                    mb: 4,
                    color: theme.palette.text.primary,
                    position: 'relative',
                    '&:after': {
                      content: '""',
                      display: 'block',
                      width: 60,
                      height: 2,
                      backgroundColor: theme.palette.primary.main,
                      mt: 2
                    }
                  }}
                >
                  Kubernetes en Raspberry Pi
                </Typography>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    lineHeight: 1.8,
                    color: theme.palette.text.secondary,
                    fontSize: '1.1rem'
                  }}
                >
                  Kubernetes es una plataforma de orquestación de contenedores que nos 
                  permite gestionar y escalar aplicaciones de manera automática. En nuestro 
                  Clúster de Raspberry Pi, Kubernetes coordina la ejecución de contenedores 
                  Docker a través de múltiples nodos, proporcionando alta disponibilidad 
                  y balanceamiento de carga.
                </Typography>
              </Paper>
            </Grid>

            {/* Benefits Sidebar */}
            <Grid item xs={12} md={4}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 4,
                  background: theme.palette.background.paper,
                  borderRadius: 1,
                  border: `1px solid ${theme.palette.divider}`,
                  height: '100%',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    boxShadow: theme.shadows[6]
                  }
                }}
              >
                <Typography 
                  variant="h5" 
                  component="h3"
                  sx={{ 
                    fontWeight: 400,
                    mb: 4,
                    color: theme.palette.text.primary,
                    position: 'relative',
                    '&:after': {
                      content: '""',
                      display: 'block',
                      width: 60,
                      height: 2,
                      backgroundColor: theme.palette.primary.main,
                      mt: 2
                    }
                  }}
                >
                  Beneficios del Clúster
                </Typography>
                <List sx={{ p: 0 }}>
                  {[
                    { icon: <Speed />, title: "Alto Rendimiento", subtitle: "Procesamiento distribuido" },
                    { icon: <Security />, title: "Alta Disponibilidad", subtitle: "Tolerancia a fallos" },
